local safePos = CFrame.new(306.18927001953125, 36.67450714111328, -519.2435913085938)
local isHiding = false
task.spawn(function()
    while true do
        if states.nightHide and not isHiding then
            local timeRemote = ReplicatedStorage:FindFirstChild("GameInfo") and ReplicatedStorage.GameInfo:FindFirstChild("TimeOfDay")
            if timeRemote and timeRemote.Value == "Night" then
                isHiding = true
                local char = LocalPlayer.Character
                if char then
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local originalPos = hrp.CFrame
                        pcall(function()
                            hrp.CFrame = safePos
                            hrp.Anchored = true
                        end)
                        repeat task.wait(0.5) until not timeRemote or timeRemote.Value ~= "Night"
                        pcall(function()
                            hrp.Anchored = false
                            hrp.CFrame = originalPos
                        end)
                    end
                end
                isHiding = false
            end
        end
        task.wait(1)
    end
end)
local InfiniteJumpEnabled = false
UserInputService.InputBegan:Connect(function(input, gameProcessed)
    if not InfiniteJumpEnabled then return end
    if input.KeyCode ~= Enum.KeyCode.Space then return end
    local char = LocalPlayer.Character
    if not char then return end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    if humanoid:GetState() == Enum.HumanoidStateType.Dead then return end
    pcall(function()
        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        humanoid.Jump = true
    end)
end)
