PlayerGroup:AddToggle('Fly', {
    Text = '飞行(安全版)',
    Default = false,
    Callback = function(Value)
        flyEnabled = Value
        local char = LocalPlayer.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum then return end

        if flyBodyVelocity then
            pcall(function() flyBodyVelocity:Destroy() end)
            flyBodyVelocity = nil
        end
        if flyBodyGyro then
            pcall(function() flyBodyGyro:Destroy() end)
            flyBodyGyro = nil
        end
        if flyThread then
            pcall(function() task.cancel(flyThread) end)
            flyThread = nil
        end

        if Value then
            flyBodyGyro = Instance.new("BodyGyro")
            flyBodyGyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
            flyBodyGyro.P = 9e4
            flyBodyGyro.CFrame = root.CFrame
            flyBodyGyro.Parent = root

            flyBodyVelocity = Instance.new("BodyVelocity")
            flyBodyVelocity.Velocity = Vector3.zero
            flyBodyVelocity.MaxForce = Vector3.new(9e9, 9e9, 9e9)
            flyBodyVelocity.Parent = root

            flyThread = task.spawn(function()
                local camera = workspace.CurrentCamera
                while flyEnabled and not Library.Unloaded do
                    local moveDir = Vector3.zero
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + camera.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - camera.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - camera.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + camera.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then moveDir = moveDir + Vector3.new(0, 1, 0) end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then moveDir = moveDir - Vector3.new(0, 1, 0) end

                    if flyBodyVelocity and flyBodyVelocity.Parent then
                        if moveDir.Magnitude > 0 then
                            flyBodyVelocity.Velocity = moveDir.Unit * flySpeed
                        else
                            flyBodyVelocity.Velocity = Vector3.zero
                        end
                    end
                    if flyBodyGyro and flyBodyGyro.Parent then
                        flyBodyGyro.CFrame = camera.CFrame
                    end
                    task.wait(0.05)
                end
                if flyBodyVelocity then
                    pcall(function() flyBodyVelocity:Destroy() end)
                    flyBodyVelocity = nil
                end
                if flyBodyGyro then
                    pcall(function() flyBodyGyro:Destroy() end)
                    flyBodyGyro = nil
                end
            end)
        else
            if flyBodyVelocity then
                pcall(function() flyBodyVelocity:Destroy() end)
                flyBodyVelocity = nil
            end
            if flyBodyGyro then
                pcall(function() flyBodyGyro:Destroy() end)
                flyBodyGyro = nil
            end
        end
    end
})

