        closebutton.Name = "Close"
        closebutton.Parent = Frame
        closebutton.BackgroundColor3 = Color3.fromRGB(225,25,0)
        closebutton.Font = Enum.Font.SourceSans
        closebutton.Size = UDim2.new(0,45,0,28)
        closebutton.Text = "X"
        closebutton.TextSize = 30
        closebutton.Position = UDim2.new(0,0,-1,27)

        mini.Name = "minimize"
        mini.Parent = Frame
        mini.BackgroundColor3 = Color3.fromRGB(192,150,230)
        mini.Font = Enum.Font.SourceSans
        mini.Size = UDim2.new(0,45,0,28)
        mini.Text = "-"
        mini.TextSize = 40
        mini.Position = UDim2.new(0,44,-1,27)

        mini2.Name = "minimize2"
        mini2.Parent = Frame
        mini2.BackgroundColor3 = Color3.fromRGB(192,150,230)
        mini2.Font = Enum.Font.SourceSans
        mini2.Size = UDim2.new(0,45,0,28)
        mini2.Text = "+"
        mini2.TextSize = 40
        mini2.Position = UDim2.new(0,44,0,30)
        mini2.Visible = false

        local speeds = 1
        local speaker = game:GetService("Players").LocalPlayer
        local chr = game.Players.LocalPlayer.Character
        local hum = chr and chr:FindFirstChildWhichIsA("Humanoid")
        local nowe = false

        Frame.Active = true
        Frame.Draggable = true

        closebutton.MouseButton1Click:Connect(function()
            main:Destroy()
        end)

        up.MouseButton1Click:Connect(function()
            if chr and chr:FindFirstChild("HumanoidRootPart") then
                chr.HumanoidRootPart.CFrame = chr.HumanoidRootPart.CFrame + Vector3.new(0, 3, 0)
            end
        end)

        down.MouseButton1Click:Connect(function()
            if chr and chr:FindFirstChild("HumanoidRootPart") then
                chr.HumanoidRootPart.CFrame = chr.HumanoidRootPart.CFrame + Vector3.new(0, -3, 0)
            end
        end)

        mini.MouseButton1Click:Connect(function()
            up.Visible = false
            down.Visible = false
            onof.Visible = false
            plus.Visible = false
            speed.Visible = false
            mine.Visible = false
            closebutton.Visible = false
            mini.Visible = false
            mini2.Visible = true
            Frame.Size = UDim2.new(0, 100, 0, 28)
            TextLabel.Position = UDim2.new(0, 0, 0, 0)
        end)

        mini2.MouseButton1Click:Connect(function()
            up.Visible = true
            down.Visible = true
            onof.Visible = true
            plus.Visible = true
            speed.Visible = true
            mine.Visible = true
            closebutton.Visible = true
            mini.Visible = true
            mini2.Visible = false
            Frame.Size = UDim2.new(0, 190, 0, 57)
            TextLabel.Position = UDim2.new(0.469327301, 0, 0, 0)
        end)

        plus.MouseButton1Click:Connect(function()
            speeds = speeds + 1
            speed.Text = tostring(speeds)
        end)

        mine.MouseButton1Click:Connect(function()
            if speeds > 1 then
                speeds = speeds - 1
                speed.Text = tostring(speeds)
            else
                speed.Text = "错误"
                task.wait(0.2)
                speed.Text = "1"
            end
        end)

        speaker.CharacterAdded:Connect(function(newChar)
            chr = newChar
            hum = chr:FindFirstChildOfClass("Humanoid")
        end)

        onof.MouseButton1Click:Connect(function()
            nowe = not nowe
            onof.Text = nowe and "飞" or "飞"
            if nowe then
                if hum then
                    for _, state in pairs(Enum.HumanoidStateType:GetEnumItems()) do
                        hum:SetStateEnabled(state, false)
                    end
                    hum:ChangeState(Enum.HumanoidStateType.Swimming)
                end
                if chr.Animate then
                    chr.Animate.Disabled = true
                end
                if hum then
                    for i,v in next,hum:GetPlayingAnimationTracks() do
                        v:AdjustSpeed(0)
                    end
                end
                task.spawn(function()
                    local runService = game:GetService("RunService")
                    while nowe and chr and hum do
                        runService.Heartbeat:Wait()
                        if hum.MoveDirection.Magnitude > 0 then
                            chr:TranslateBy(hum.MoveDirection * speeds)
                        end
                    end
                end)
                if hum.RigType == Enum.HumanoidRigType.R6 then
                    local plr = game.Players.LocalPlayer
                    local torso = plr.Character.Torso
                    local bg = Instance.new("BodyGyro", torso)
                    bg.P = 9e4
                    bg.maxTorque = Vector3.new(9e9,9e9,9e9)
                    bg.CFrame = torso.CFrame
                    local bv = Instance.new("BodyVelocity", torso)
                    bv.Velocity = Vector3.new(0,0,0)
                    bv.MaxForce = Vector3.new(9e9,9e9,9e9)
                    if nowe then
                        plr.Character.Humanoid.PlatformStand = true
                    end
                    while nowe and plr.Character.Humanoid.Health > 0 do
                        game:GetService("RunService").RenderStepped:Wait()
                        bg.CFrame = workspace.CurrentCamera.CoordinateFrame
                    end
                    bg:Destroy()
                    bv:Destroy()
                    plr.Character.Humanoid.PlatformStand = false
                    plr.Character.Animate.Disabled = false
                else
                    local plr = game.Players.LocalPlayer
                    local UpperTorso = plr.Character.UpperTorso
                    local bg = Instance.new("BodyGyro", UpperTorso)
                    bg.P = 9e4
                    bg.maxTorque = Vector3.new(9e9,9e9,9e9)
                    bg.CFrame = UpperTorso.CFrame
                    local bv = Instance.new("BodyVelocity", UpperTorso)
                    bv.Velocity = Vector3.new(0,0,0)
                    bv.MaxForce = Vector3.new(9e9,9e9,9e9)
                    if nowe then
                        plr.Character.Humanoid.PlatformStand = true
                    end
                    while nowe and plr.Character.Humanoid.Health > 0 do
                        task.wait()
                        bg.CFrame = workspace.CurrentCamera.CoordinateFrame
                    end
                    bg:Destroy()
                    bv:Destroy()
                    plr.Character.Humanoid.PlatformStand = false
                    plr.Character.Animate.Disabled = false
                end
            else
                if hum then
                    for _, state in pairs(Enum.HumanoidStateType:GetEnumItems()) do
                        hum:SetStateEnabled(state, true)
                    end
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                end
                if chr.Animate then
                    chr.Animate.Disabled = false
                end
            end
        end)
    end)

    if success then
        Notify("飞行脚本已加载")
    else
        Notify("飞行脚本出错：" .. tostring(err))
    end
end

