local CircleCenterX, CircleCenterZ = 0, 0
for _, c in pairs(BaseCoords) do
    CircleCenterX = CircleCenterX + c[1]
    CircleCenterZ = CircleCenterZ + c[3]
end
CircleCenterX = CircleCenterX / #BaseCoords
