	["种植花园2"] = [[local function safeLoad(url) local success, result = pcall(function() return loadstring(game:HttpGet(url))() end) if not success then warn("加载失败: " .. url) return nil end return result end local Library = safeLoad("https://raw.githubusercontent.com/kongbaNB/ui/refs/heads/main/黑曜石主库.ui") local ThemeManager = safeLoad("https://raw.githubusercontent.com/kongbaNB/ui/refs/heads/main/主题管理.ui") local SaveManager = safeLoad("https://raw.githubusercontent.com/kongbaNB/ui/refs/heads/main/配置管理.ui") if not Library then game:GetService("StarterGui"):SetCore("SendNotification", { Title = "错误", Text = "UI 库加载失败，请检查网络或脚本资源", Duration = 5, }) return end
local Options = Library.Options local Toggles = Library.Toggles local Players = game:GetService("Players") local ReplicatedStorage = game:GetService("ReplicatedStorage") local player = Players.LocalPlayer local Window = Library:CreateWindow({ Title = "种植花园2", Footer = "恐拜大帝 制作", Icon = 131153193945220, NotifySide = "Right", ShowCustomCursor = true, }) Library:Notify({ Title = "种植花园2", Description = "创作者：恐拜大帝\nQQ：3999698324\n脚本已加载成功", Time = 5, }) local Tabs = { Notice = Window:AddTab("通知", "info"), Main = Window:AddTab("主要", "info"), Settings = Window:AddTab("设置", "settings"), }

local Workspace = game:GetService("Workspace")
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer

local espEnabled = false
local espData = {}
local weightSources = {}
local scanFruits
local clearAll
local getWeight

local goldColor = Color3.fromRGB(255, 200, 40)

local translatedTexts = {}

local function translateText(text)
    if not text or text == "" or #text < 2 then
        return nil
    end
    local cached = translatedTexts[text]
    if cached ~= nil then
        if cached == false then return nil end
        return cached
    end
    local success, result = pcall(function()
        local url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=zh-CN&dt=t&q=" .. HttpService:UrlEncode(text)
        local response = game:HttpGet(url)
        local decoded = HttpService:JSONDecode(response)
        if decoded and decoded[1] and decoded[1][1] and decoded[1][1][1] then
            return decoded[1][1][1]
        end
        return nil
    end)
    if success and result then
        translatedTexts[text] = result
        return result
    end
    return nil
end

local function isEnglish(text)
    if not text or text == "" then
        return false
    end
    local englishCount = 0
    local totalCount = 0
    for char in text:gmatch(".") do
        local byte = string.byte(char)
        if byte then
            totalCount = totalCount + 1
            if (byte >= 65 and byte <= 90) or (byte >= 97 and byte <= 122) then
                englishCount = englishCount + 1
            end
        end
    end
    if totalCount == 0 then
        return false
    end
    return (englishCount / totalCount) > 0.5
end

local function toggleValue(key, default)
    local ok, v = pcall(function() return Toggles[key].Value end)
    if ok and v ~= nil then return v end
    return default
end

local function nameOn() return toggleValue("PlantESP_Name", true) end
local function weightOn() return toggleValue("PlantESP_Weight", true) end
local function distOn() return toggleValue("PlantESP_Dist", false) end
local function fillOn() return toggleValue("PlantESP_Fill", false) end

local function getMinKG()
    local ok, v = pcall(function() return Options.PlantESP_MinKG.Value end)
    if ok and type(v) == "number" then return v end
    return 0
end

local function passFilter(fruit)
    local w = getWeight(fruit)
    if w == nil then return true end
    return w >= getMinKG()
end

local function composeLabel(data)
    local parts = {}
    if nameOn() and data.name then
        table.insert(parts, data.name)
    end
    if weightOn() and data.weight then
        table.insert(parts, string.format("%.2fkg", data.weight))
    end
    if distOn() and data.dist then
        table.insert(parts, string.format("%.0f米", data.dist))
    end
    return table.concat(parts, "\n")
end

local function refreshLabel(data)
    if not data.label or not data.label.Parent then return end
    local text = composeLabel(data)
    if text ~= data.lastText then
        data.lastText = text
        data.label.Text = text
    end
    if data.billboard and data.billboard.Parent then
        data.billboard.Enabled = (text ~= "")
    end
end

local function refreshESP()
    if espEnabled then
        clearAll()
        scanFruits()
    end
end

local filterPending = false
local function scheduleFilterRefresh()
    if filterPending then return end
    filterPending = true
    task.delay(0.4, function()
        filterPending = false
        refreshESP()
    end)
end

local NoticeGroup = Tabs.Notice:AddLeftGroupbox("作者消息") NoticeGroup:AddLabel('恐拜大帝将持续更新此脚本') NoticeGroup:AddLabel('创作者：恐拜大帝') local UnloadGroup = Tabs.Settings:AddLeftGroupbox("脚本管理") UnloadGroup:AddButton("卸载脚本", function() Library:Unload() end)

local PlantGroup = Tabs.Main:AddLeftGroupbox("植物透视")
