            end
        end)
    end)
end
for _, key in ipairs({"PlantESP_Name", "PlantESP_Weight", "PlantESP_Dist"}) do
    if Toggles[key] then
        Toggles[key]:OnChanged(function()
            pcall(function()
                for fruit, data in pairs(espData) do
                    refreshLabel(data)
                end
            end)
