Title = "旋转开启",
Content = "旋转速度: " .. SpinSpeed,
Duration = 2,
Icon = "refresh-cw"
})
else
WindUI:Notify({
Title = "旋转关闭",
Content = "旋转功能已禁用",
Duration = 2,
Icon = "x"
})
end
end
