        autoChop = Value
        if Value then
            task.spawn(function()
                pcall(function()
                    refreshTrees(true)
                    Library:Notify({
                        Title = "自动砍树",
                        Description = "搜索完成，找到 " .. #treeList .. " 棵树",
                        Time = 4,
                    })
                end)
            end)
        end
    end,
})

Toggles.AutoChop:OnChanged(function(Value)
    autoChop = Value
end)

