    Callback = function(Value)
        killAuraRange = Value
    end
})

task.spawn(function()
    while true do
        if killAuraEnabled and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
            local hrp = player.Character.HumanoidRootPart
            local camPos = camera.CFrame.Position
            local enemies = refreshEnemies()
            updateDummies()
            local gun = getEquippedGun()
            if gun then
                local events = gun:FindFirstChild("Events")
                if events then
                    local fireEvent = events:FindFirstChild("Fire")
                    if fireEvent and fireEvent:IsA("RemoteEvent") then
                        local nearestEnemy = nil
                        local nearestPart = nil
                        local minDist = math.huge
                        for _, enemy in ipairs(enemies) do
                            if enemy and enemy.Parent then
                                local part = getEnemyPart(enemy)
                                if part then
                                    local dist = (part.Position - hrp.Position).Magnitude
                                    if dist <= killAuraRange and dist < minDist then
                                        minDist = dist
                                        nearestEnemy = enemy
                                        nearestPart = part
                                    end
                                end
                            end
                        end
                        if nearestPart then
                            local origin = camPos
                            local hitPos = nearestPart.Position
                            local dir = (hitPos - origin).Unit
                            local bulletData = {}
                            bulletData[1] = {}
                            bulletData[1][1] = {}
                            bulletData[1][1]["HitInstance"] = nearestPart
                            bulletData[1][1]["Direction"] = dir
                            bulletData[1][1]["HitPosition"] = hitPos
                            bulletData[1][1]["Origin"] = origin
                            bulletData[2] = camera.CFrame
                            pcall(function()
                                fireEvent:FireServer(unpack(bulletData))
                            end)
                        end
                    end
                end
            else
                local fists = player.Character:FindFirstChild("Fists")
                if fists then
                    local events = fists:FindFirstChild("Events")
                    if events then
                        local attackEvent = events:FindFirstChild("Attack")
                        if attackEvent and attackEvent:IsA("RemoteEvent") then
                            local nearestEnemy = nil
                            local nearestPart = nil
                            local minDist = math.huge
                            for _, enemy in ipairs(enemies) do
                                if enemy and enemy.Parent then
                                    local part = getEnemyPart(enemy)
                                    if part then
                                        local dist = (part.Position - hrp.Position).Magnitude
                                        if dist <= killAuraRange and dist < minDist then
                                            minDist = dist
                                            nearestEnemy = enemy
                                            nearestPart = part
                                        end
                                    end
                                end
                            end
                            if nearestPart then
                                createDummy(nearestEnemy)
                                local dir = (nearestPart.Position - hrp.Position).Unit
                                pcall(function()
                                    attackEvent:FireServer(dir)
                                end)
                            end
                        end
                    end
                end
            end
        else
            clearDummies()
        end
        task.wait(0.4)
    end
end)

local bulletAimEnabled = false
local hookedTools = {}

local function hookTool(tool)
    if hookedTools[tool] then return end
    local events = tool:FindFirstChild("Events")
    if not events then return end
    local fireEvent = events:FindFirstChild("Fire")
    local readyEvent = events:FindFirstChild("Ready")
    if fireEvent and fireEvent:IsA("RemoteEvent") then
        local oldFire = fireEvent.FireServer
        fireEvent.FireServer = function(self, ...)
            if not bulletAimEnabled then
                return oldFire(self, ...)
            end
            local args = {...}
            if args[1] and typeof(args[1]) == "table" and args[1][1] and typeof(args[1][1]) == "table" then
                local target = nil
                local minDist = math.huge
                local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                for _, enemy in ipairs(refreshEnemies()) do
                    if enemy and enemy.Parent then
                        local part = getEnemyPart(enemy)
                        if part and hrp then
                            local d = (part.Position - hrp.Position).Magnitude
                            if d < minDist then
                                minDist = d
                                target = part
                            end
                        end
                    end
                end
                if target then
                    local origin = args[1][1].Origin
                    if not origin and hrp then
                        origin = hrp.Position
                    end
                    if origin then
                        args[1][1].HitInstance = target
                        args[1][1].HitPosition = target.Position
                        args[1][1].Direction = (target.Position - origin).Unit
                    end
                end
            end
            return oldFire(self, unpack(args))
        end
    end
    if readyEvent and readyEvent:IsA("RemoteEvent") then
        local oldReady = readyEvent.FireServer
        readyEvent.FireServer = function(self, ...)
            if bulletAimEnabled then
                return
            end
            return oldReady(self, ...)
        end
    end
    hookedTools[tool] = true
end

local function scanAndHookTools()
    local char = player.Character
    if not char then return end
    for _, tool in ipairs(char:GetDescendants()) do
        if tool:IsA("Tool") or tool:IsA("Model") then
            local events = tool:FindFirstChild("Events")
            if events and events:FindFirstChild("Fire") then
                hookTool(tool)
            end
        end
    end
end

player.CharacterAdded:Connect(function(char)
    hookedTools = {}
    char:WaitForChild("Humanoid")
    task.wait(0.5)
    scanAndHookTools()
    char.DescendantAdded:Connect(function(desc)
        if (desc:IsA("Tool") or desc:IsA("Model")) and desc:FindFirstChild("Events") and desc.Events:FindFirstChild("Fire") then
            task.wait(0.2)
            hookTool(desc)
        end
    end)
end)

if player.Character then
    scanAndHookTools()
    player.Character.DescendantAdded:Connect(function(desc)
        if (desc:IsA("Tool") or desc:IsA("Model")) and desc:FindFirstChild("Events") and desc.Events:FindFirstChild("Fire") then
            task.wait(0.2)
            hookTool(desc)
        end
    end)
end

AimGroup:AddToggle("BulletAim", {
    Text = "子弹追踪",
    Default = false,
    Callback = function(Value)
        bulletAimEnabled = Value
        if Value then
            scanAndHookTools()
            Library:Notify({Title = "子弹追踪", Description = "已开启", Time = 3})
        end
    end
})

if draggableFolder then
    draggableFolder.ChildAdded:Connect(function(child)
        if espEnabled and child:IsA("Model") then
            task.wait(0.3)
            local part = getPrimaryPart(child)
            if part then
                local hl = Instance.new("Highlight")
                hl.Name = "ItemHighlight"
                hl.Adornee = child
                hl.OutlineColor = Color3.fromRGB(255, 255, 0)
                hl.FillColor = Color3.fromRGB(255, 255, 0)
                hl.OutlineTransparency = 1
                hl.FillTransparency = 1
                hl.Parent = child
                table.insert(allEspItems, {item = child, part = part, hl = hl})
            end
        end
    end)
    draggableFolder.ChildRemoved:Connect(function(child)
        for i = #allEspItems, 1, -1 do
            if allEspItems[i].item == child then
                if allEspItems[i].hl then
                    allEspItems[i].hl:Destroy()
                end
                table.remove(allEspItems, i)
                break
            end
        end
        if itemLabelMap[child] then
            recycleLabel(itemLabelMap[child].nl, labelPool)
            recycleLabel(itemLabelMap[child].dl, labelPool)
            itemLabelMap[child] = nil
        end
    end)
end
