local function notify(title, msg, t)
    Library:Notify({ Title = title, Description = msg, Time = t or 4 })
end

local function http_get(url)
    local request_func = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
    if request_func then
        local ok, response = pcall(function() return request_func({Url = url, Method = "GET"}) end)
        if ok and response and response.StatusCode == 200 then return response.Body end
    end
    local ok2, body = pcall(function() return game:HttpGet(url) end)
    if ok2 then return body end
    return nil
end

local CanvasWatcher = {
    running = false,
    conn = nil,
    target = nil,
    size = nil,
    importBuf = nil,
    prevBuf = nil,
    userOverlay = {},
    bg = {255, 255, 255, 255},
}

local function stopCanvasWatcher()
    if CanvasWatcher.conn then
        CanvasWatcher.conn:Disconnect()
        CanvasWatcher.conn = nil
    end
    CanvasWatcher.running = false
end

local function startCanvasWatcher(targetImage, importBuf, canvasSize, bgPixel)
    stopCanvasWatcher()
    CanvasWatcher.target = targetImage
    CanvasWatcher.size = canvasSize
    CanvasWatcher.importBuf = importBuf
    CanvasWatcher.prevBuf = buffer.create(buffer.len(importBuf))
    buffer.copy(CanvasWatcher.prevBuf, 0, importBuf, 0)
    CanvasWatcher.userOverlay = {}
    CanvasWatcher.bg = bgPixel
    CanvasWatcher.running = true
    local totalPixels = canvasSize.X * canvasSize.Y
    local wipeThreshold = math.max(8, math.floor(totalPixels * 0.25))
    CanvasWatcher.conn = game:GetService("RunService").Heartbeat:Connect(function()
        if not CanvasWatcher.running then return end
        local readOk, cur = pcall(function()
            return targetImage:ReadPixelsBuffer(Vector2.zero, canvasSize)
        end)
        if not readOk or not cur then return end
        local prev = CanvasWatcher.prevBuf
        local imp = CanvasWatcher.importBuf
        local bg = CanvasWatcher.bg
        local changed = {}
        for i = 0, totalPixels - 1 do
            local o = i * 4
            if buffer.readu32(cur, o) ~= buffer.readu32(prev, o) then
                changed[#changed + 1] = o
            end
        end
        if #changed == 0 then return end
        local function isBg(o)
            return buffer.readu8(cur, o) == bg[1]
                and buffer.readu8(cur, o + 1) == bg[2]
                and buffer.readu8(cur, o + 2) == bg[3]
        end
        if #changed > wipeThreshold then
            for _, o in ipairs(changed) do
                if buffer.readu32(cur, o) ~= buffer.readu32(imp, o) and not isBg(o) then
                    CanvasWatcher.userOverlay[o] = {
                        buffer.readu8(cur, o),
                        buffer.readu8(cur, o + 1),
                        buffer.readu8(cur, o + 2),
                        buffer.readu8(cur, o + 3),
                    }
                end
            end
            local merged = buffer.create(buffer.len(imp))
            buffer.copy(merged, 0, imp, 0)
            for o, px in pairs(CanvasWatcher.userOverlay) do
                buffer.writeu8(merged, o, px[1])
                buffer.writeu8(merged, o + 1, px[2])
                buffer.writeu8(merged, o + 2, px[3])
                buffer.writeu8(merged, o + 3, px[4])
            end
            pcall(function()
                targetImage:WritePixelsBuffer(Vector2.zero, canvasSize, merged)
            end)
            buffer.copy(prev, 0, merged, 0)
        else
            for _, o in ipairs(changed) do
                if buffer.readu32(cur, o) ~= buffer.readu32(imp, o) and not isBg(o) then
                    CanvasWatcher.userOverlay[o] = {
                        buffer.readu8(cur, o),
                        buffer.readu8(cur, o + 1),
                        buffer.readu8(cur, o + 2),
                        buffer.readu8(cur, o + 3),
                    }
                end
            end
            buffer.copy(prev, 0, cur, 0)
        end
    end)
end

local function drawImageToCanvas(fileData, fileType)
    local targetImage = canvas.get_canvas()
    if not targetImage then
        notify("画我", "没有找到画布，先站到画板前面再点", 5)
        return false
    end
    if fileType ~= "PNG" and fileType ~= "JPG" then
        notify("画我", "格式不支持，只支持 PNG 和 JPG", 5)
        return false
    end
    local canvasSize = targetImage.Size
    local parseOk, image = pcall(function() return image_loader.load(fileData, fileType) end)
    if not parseOk or not image then
        notify("画我", "图片解析失败", 5)
        return false
    end
    local srcWidth, srcHeight = image.Width, image.Height
    local dstWidth = canvasSize.X
    local dstHeight = canvasSize.Y
    local bufferSize = dstWidth * dstHeight * 4
    local pixelBuffer = buffer.create(bufferSize)
    local ratioX = srcWidth / dstWidth
    local ratioY = srcHeight / dstHeight
    local pointer = 0
    for y = 1, dstHeight do
        local sampleY = math.floor((y - 1) * ratioY) + 1
        if sampleY > srcHeight then sampleY = srcHeight end
        for x = 1, dstWidth do
            local sampleX = math.floor((x - 1) * ratioX) + 1
            if sampleX > srcWidth then sampleX = srcWidth end
            local color, alpha = image:GetPixel(sampleX, sampleY)
            local aVal = alpha or 1
            buffer.writeu8(pixelBuffer, pointer,     math.floor(color.R * 255))
            buffer.writeu8(pixelBuffer, pointer + 1, math.floor(color.G * 255))
            buffer.writeu8(pixelBuffer, pointer + 2, math.floor(color.B * 255))
            buffer.writeu8(pixelBuffer, pointer + 3, math.floor(aVal * 255))
            pointer = pointer + 4
        end
    end
    local bgPixel = {255, 255, 255, 255}
    local bgOk, bgBuf = pcall(function()
        return targetImage:ReadPixelsBuffer(Vector2.zero, Vector2.new(1, 1))
    end)
    if bgOk and bgBuf and buffer.len(bgBuf) >= 4 then
        bgPixel = {
            buffer.readu8(bgBuf, 0),
            buffer.readu8(bgBuf, 1),
            buffer.readu8(bgBuf, 2),
            buffer.readu8(bgBuf, 3),
        }
    end
    local writeSuccess, writeErr = pcall(function()
        targetImage:WritePixelsBuffer(Vector2.zero, canvasSize, pixelBuffer)
    end)
    if not writeSuccess then
        notify("画我", "写入画布失败", 5)
        return false
    end
    startCanvasWatcher(targetImage, pixelBuffer, canvasSize, bgPixel)
    return true
end

local function importAndDraw()
    task.spawn(function()
        local selection = source_selector.Select({
            extensions = {".png", ".jpg", ".jpeg"}
        })
        if not selection then
            notify("画我", "没有选择图片", 4)
            return
        end
        notify("画我", "正在解析并绘制图片…", 3)
        local ok = drawImageToCanvas(selection.Data, selection.Type)
        if ok then
            notify("画我", "绘制完成", 4)
        end
    end)
end

