    PreviewFrame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true; dragStart = input.Position; startPos = PreviewFrame.Position
            input.Changed:Connect(function() if input.UserInputState == Enum.UserInputState.End then dragging = false end end)
        end
    end)
    PreviewFrame.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then dragInput = input end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            local delta = input.Position - dragStart
            PreviewFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)
end

local function getAvatarContent(target, thumbType)
    local ok, content = pcall(function()
        return Players:GetUserThumbnailAsync(target.UserId, thumbType, Enum.ThumbnailSize.Size150x150)
    end)
    if ok then return content end
    return nil
end

local function applyShrinkState()
    if avatarShrunk then
        PreviewFrame.Size = UDim2.new(0, 60, 0, 60)
        PreviewTitle.Visible = false
        ShrinkBtn.Visible = false
        PreviewImage.Position = UDim2.new(0, 3, 0, 3)
        PreviewImage.Size = UDim2.new(1, -6, 1, -6)
    else
        PreviewFrame.Size = UDim2.new(0, 150, 0, 220)
        PreviewTitle.Visible = true
        ShrinkBtn.Visible = true
        PreviewImage.Position = UDim2.new(0, 10, 0, 30)
        PreviewImage.Size = UDim2.new(1, -20, 1, -70)
    end
end

ShrinkBtn.MouseButton1Click:Connect(function()
    avatarShrunk = not avatarShrunk
    applyShrinkState()
    if avatarShrunk and selectedPlayerName then
        local target = Players:FindFirstChild(selectedPlayerName)
        if target then
            task.spawn(function()
                local content = getAvatarContent(target, Enum.ThumbnailType.HeadShot)
                if content then PreviewImage.Image = content end
            end)
        end
    elseif selectedPlayerName then
        local target = Players:FindFirstChild(selectedPlayerName)
        if target then
            task.spawn(function()
                local content = getAvatarContent(target, Enum.ThumbnailType.AvatarBust)
                if content then PreviewImage.Image = content end
            end)
        end
    end
end)

local function refreshInnerImage()
    local img = Options.PlayerAvatarInner
    if not img then return end
    if not Toggles.ShowAvatar1 or not Toggles.ShowAvatar1.Value then
        img:SetVisible(false)
        return
    end
    if not selectedPlayerName then
        img:SetVisible(false)
        return
    end
    local target = Players:FindFirstChild(selectedPlayerName)
    if not target then
        img:SetVisible(false)
        return
    end
    task.spawn(function()
        local content = getAvatarContent(target, Enum.ThumbnailType.AvatarBust)
        if content then
            img:SetImage(content)
            img:SetVisible(true)
        end
    end)
end

local function refreshOuterImage()
    if not Toggles.ShowAvatar2 or not Toggles.ShowAvatar2.Value then
        PreviewFrame.Visible = false
        return
    end
    PreviewFrame.Visible = true
    if not selectedPlayerName then
        PreviewTitle.Text = "未选择玩家"
        PreviewImage.Image = ""
        return
    end
    local target = Players:FindFirstChild(selectedPlayerName)
    if not target then
        PreviewTitle.Text = "玩家已离开"
        PreviewImage.Image = ""
        return
    end
    PreviewTitle.Text = target.DisplayName .. " (@" .. target.Name .. ")"
    task.spawn(function()
        local thumbType = avatarShrunk and Enum.ThumbnailType.HeadShot or Enum.ThumbnailType.AvatarBust
        local content = getAvatarContent(target, thumbType)
        if content then PreviewImage.Image = content end
    end)
end

local NameTags = {}

local function removeNameTag(plr)
    local tag = NameTags[plr]
    if tag then
        tag:Destroy()
        NameTags[plr] = nil
    end
end

local function addNameTag(plr)
    removeNameTag(plr)
    local char = plr.Character
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end
    local bb = Instance.new("BillboardGui")
    bb.Name = "DrawMeNameTag"
    bb.Adornee = head
    bb.Size = UDim2.new(0, 200, 0, 40)
    bb.StudsOffset = Vector3.new(0, 2.5, 0)
    bb.AlwaysOnTop = true
    local tl = Instance.new("TextLabel")
    tl.Parent = bb
    tl.BackgroundTransparency = 1
    tl.Size = UDim2.new(1, 0, 1, 0)
    tl.Font = Enum.Font.GothamBold
    tl.Text = plr.DisplayName
    tl.TextColor3 = Color3.new(1, 1, 1)
    tl.TextStrokeTransparency = 0.5
    tl.TextSize = 16
    bb.Parent = head
    NameTags[plr] = bb
end

local function clearAllNameTags()
    for plr, _ in pairs(NameTags) do
        removeNameTag(plr)
    end
end

local function refreshAllNameTags()
    clearAllNameTags()
    if Toggles.ShowAllNames and Toggles.ShowAllNames.Value then
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= player then
                addNameTag(plr)
            end
        end
    end
end

local function getPlayerNames()
    local names = {}
    for _, p in ipairs(Players:GetPlayers()) do
        table.insert(names, p.Name)
    end
    table.sort(names)
    return names
end

local function getPlayerAvatarData(userId)
    local apiUrl = string.format("https://thumbnails.roblox.com/v1/users/avatar?userIds=%d&size=420x420&format=Png&isCircular=false", userId)
    local jsonBody = http_get(apiUrl)
    if not jsonBody then return nil end
    local ok, decoded = pcall(function() return HttpService:JSONDecode(jsonBody) end)
    if not ok or not decoded or not decoded.data or not decoded.data[1] then return nil end
    local imageUrl = decoded.data[1].imageUrl
    if not imageUrl then return nil end
    local imageData = http_get(imageUrl)
    return imageData
end

local function drawSelectedPlayer()
    if not selectedPlayerName then
        notify("画我", "先在下拉框里选一个玩家", 4)
        return
    end
    local target = Players:FindFirstChild(selectedPlayerName)
    if not target then
        notify("画我", "这个玩家已经离开服务器了", 4)
        return
    end
    task.spawn(function()
        notify("画我", "正在获取 " .. target.Name .. " 的形象…", 3)
        local imageData = getPlayerAvatarData(target.UserId)
        if not imageData then
            notify("画我", "获取玩家形象失败，网络问题或接口被拦", 5)
            return
        end
        notify("画我", "正在绘制到画布…", 3)
        local ok = drawImageToCanvas(imageData, "PNG")
        if ok then
            notify("画我", "已把 " .. target.Name .. " 画出来了", 4)
        end
    end)
end

