local function makeEspToggle(name, collectFunc)
    local drawings = {}
    local conn = nil
    local function clearAll()
        for _, d in ipairs(drawings) do
            pcall(function()
                d:Remove()
            end)
        end
        drawings = {}
    end
    EspGroup:AddToggle(name, { Text = name, Default = false })
    Toggles[name]:OnChanged(function(v)
        if v then
            conn = RunService.RenderStepped:Connect(function()
                for _, d in ipairs(drawings) do
                    pcall(function()
                        d.Visible = false
                    end)
                end
                local char = player.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then
                    return
                end
                local cam = Workspace.CurrentCamera
                if not cam then
                    return
                end
                local i = 0
                for _, model in ipairs(collectFunc()) do
                    local root = getRootPart(model)
                    if root then
                        local pos, onScreen = cam:WorldToViewportPoint(root.Position)
                        if onScreen then
                            i = i + 1
                            local d = drawings[i]
                            if not d then
                                d = Drawing.new("Text")
                                d.Size = 16
                                d.Center = true
                                d.Outline = true
                                d.Color = Color3.fromRGB(255, 255, 255)
                                drawings[i] = d
                            end
                            local dist = (hrp.Position - root.Position).Magnitude
                            d.Text = displayName(model.Name) .. " [" .. math.floor(dist) .. "m]"
                            d.Position = Vector2.new(pos.X, pos.Y)
                            d.Visible = true
                        end
                    end
                end
            end)
        else
            if conn then
                conn:Disconnect()
                conn = nil
            end
            clearAll()
        end
    end)
end

