VipGroup:AddButton("获取所有付费道具", function()
    local backpack = player:WaitForChild("Backpack")
    local vipNames = {
        ["vip coil"] = true, ["freeze gun"] = true, ["radio"] = true,
        ["rainbow flashlight"] = true, ["jetpack"] = true,
        ["ghostly coil"] = true, ["magic carpet"] = true,
        ["guest's grimoire"] = true, ["slap hand"] = true,
        ["stolen knife"] = true, ["insanity coil"] = true,
        ["body swap potion"] = true, ["god mode"] = true,
        ["second chance"] = true, ["ruler"] = true, ["bloxy award"] = true
    }
    local function isVIP(name)
        return vipNames[name:lower()] == true
    end
    local count = 0
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= player then
            local bp = p:FindFirstChild("Backpack")
            if bp then
                for _, tool in ipairs(bp:GetChildren()) do
                    if tool:IsA("Tool") and isVIP(tool.Name) and not backpack:FindFirstChild(tool.Name) then
                        tool:Clone().Parent = backpack
                        count = count + 1
                    end
                end
            end
            local c = p.Character
            if c then
                for _, tool in ipairs(c:GetChildren()) do
                    if tool:IsA("Tool") and isVIP(tool.Name) and not backpack:FindFirstChild(tool.Name) then
                        tool:Clone().Parent = backpack
                        count = count + 1
                    end
                end
            end
        end
    end
    local vipGivers = workspace:FindFirstChild("VIP Givers")
    if vipGivers then
        for _, item in ipairs(vipGivers:GetChildren()) do
            if not backpack:FindFirstChild(item.Name) then
                local tool = Instance.new("Tool")
                tool.Name = item.Name
                tool.CanBeDropped = true
                local model = item:Clone()
                model.Name = "Handle"
                local primary = model:FindFirstChildWhichIsA("BasePart", true)
                if primary then
                    for _, part in ipairs(model:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.Anchored = false
                            part.CanCollide = false
                            if part ~= primary then
                                local weld = Instance.new("Weld")
                                weld.Part0 = primary
                                weld.Part1 = part
                                weld.C0 = primary.CFrame:Inverse() * part.CFrame
                                weld.Parent = primary
                            end
                        end
                    end
                    model.Parent = tool
                end
                tool.Parent = backpack
                count = count + 1
            end
        end
    end
    Library:Notify("获取完成(" .. count .. ")", 3)
end)

local KillGroup = Tabs.Kill:AddLeftGroupbox("杀戮功能")

local function killAllMonsters()
    for _, obj in ipairs(Workspace:GetDescendants()) do
        if obj:IsA("Humanoid") and obj.Parent then
            local model = obj.Parent
            local isPlayer = false
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Character == model then
                    isPlayer = true
                    break
                end
            end
            if not isPlayer then
                pcall(function()
                    obj.Health = 0
                end)
                task.delay(0.2, function()
                    pcall(function()
                        if model and model.Parent then
                            model:Destroy()
                        end
                    end)
                end)
            end
        end
    end
end

KillGroup:AddButton("杀戮全部怪物", function()
    killAllMonsters()
end)

