GeneralLeft:AddToggle("自动复活开关", {
    Text = "开启/关闭自动复活",
    Default = false,
    Callback = function(value)
        states.autoRespawn = value
        if states.autoRespawn then
            local function setupRespawn(char)
                local hum = char:WaitForChild("Humanoid")
                hum.Died:Connect(function()
                    if states.autoRespawn then
                        task.wait(0.5)
                        player:LoadCharacter()
                    end
                end)
            end
            if player.Character then
                setupRespawn(player.Character)
            end
            if states.respawnConn then states.respawnConn:Disconnect() end
            states.respawnConn = player.CharacterAdded:Connect(setupRespawn)
        else
            if states.respawnConn then states.respawnConn:Disconnect() states.respawnConn = nil end
        end
    end
})

