local autoScrapEnabled = false

local function getScraps()
    local scraps = {}
    local currentMap = Workspace:FindFirstChild("CurrentMap")
    if currentMap then
        local scrapWorld = currentMap:FindFirstChild("FH_ScrapWorld")
        if scrapWorld then
            for _, obj in ipairs(scrapWorld:GetDescendants()) do
                if obj:FindFirstChild("ProximityPrompt") then
                    table.insert(scraps, obj)
                end
            end
        end
    end
    return scraps
end

MiscLeft:AddToggle("自动捡废料", {
