MiscLeft:AddToggle("夜视", {
    Text = "夜视",
    Default = false,
    Tooltip = "黑暗中看清一切",
}):OnChanged(function(value)
    if value then
        Lighting:SetAttribute("_orig_brightness", Lighting.Brightness)
        Lighting:SetAttribute("_orig_ambient", Lighting.Ambient)
        Lighting:SetAttribute("_orig_outdoor", Lighting.OutdoorAmbient)
        Lighting:SetAttribute("_orig_clock", Lighting.ClockTime)
        Lighting.Brightness = 4
        Lighting.Ambient = Color3.fromRGB(160, 160, 160)
        Lighting.OutdoorAmbient = Color3.fromRGB(160, 160, 160)
        Lighting.ClockTime = 12
        local cc = Lighting:FindFirstChildOfClass("ColorCorrectionEffect")
        if not cc then
            cc = Instance.new("ColorCorrectionEffect")
            cc.Name = "NightVisionCC"
            cc.Parent = Lighting
        end
        cc:SetAttribute("_orig_contrast", cc.Contrast)
        cc:SetAttribute("_orig_saturation", cc.Saturation)
        cc:SetAttribute("_orig_tint", cc.TintColor)
        cc.Contrast = 0.2
        cc.Saturation = 0.15
        cc.TintColor = Color3.fromRGB(255, 255, 255)
        cc.Enabled = true
    else
        local ob = Lighting:GetAttribute("_orig_brightness")
        local oa = Lighting:GetAttribute("_orig_ambient")
        local oo = Lighting:GetAttribute("_orig_outdoor")
        local oc = Lighting:GetAttribute("_orig_clock")
        if ob ~= nil then Lighting.Brightness = ob end
        if oa ~= nil then Lighting.Ambient = oa end
        if oo ~= nil then Lighting.OutdoorAmbient = oo end
        if oc ~= nil then Lighting.ClockTime = oc end
        for _, obj in ipairs(Lighting:GetChildren()) do
            if obj:IsA("ColorCorrectionEffect") and obj.Name == "NightVisionCC" then
                local c = obj:GetAttribute("_orig_contrast")
                local s = obj:GetAttribute("_orig_saturation")
                local t = obj:GetAttribute("_orig_tint")
                if c ~= nil then obj.Contrast = c end
                if s ~= nil then obj.Saturation = s end
                if t ~= nil then obj.TintColor = t end
                obj:Destroy()
            end
        end
    end
end)

