                local skip = false
                local p = obj
                while p do
                    if p == character then
                        skip = true
                        break
                    end
                    local entities = Workspace:FindFirstChild("Entities")
                    if entities and p.Parent == entities then
                        skip = true
                        break
                    end
                    p = p.Parent
                end
                if not skip then
                    local pl = Instance.new("PointLight")
                    pl.Name = "FullBrightLight"
                    pl.Brightness = 1.5
                    pl.Range = 15
                    pl.Color = Color3.fromRGB(255, 250, 240)
                    pl.Parent = obj
                end
            end
        end
    else
        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") then
                for _, child in ipairs(obj:GetChildren()) do
                    if child.Name == "FullBrightLight" and child:IsA("PointLight") then
                        child:Destroy()
                    end
                end
            end
        end
    end
end)

