    FireDelay = 0.1,
    Target = nil,
}

local KillAura = {
    Enabled = false,
    Range = 20,
    Interval = 0.1,
    FixedDamage = 100,
    LastAttack = 0,
    Version = "v1",
}

local ESP = {
    Enabled = false,
