FOVCorner.CornerRadius = UDim.new(1, 0)

local function getEquippedWeapon()
    local char = player.Character
    if not char then return nil end
    return char:FindFirstChildOfClass("Tool")
end

local function isValidTarget(plr)
    if not plr or plr == player then return false end
    if not plr.Character then return false end
    local head = plr.Character:FindFirstChild("Head")
    local humanoid = plr.Character:FindFirstChild("Humanoid")
    if not head or not humanoid then return false end
    if humanoid.Health <= 0 then return false end
    if Aimbot.TeamCheck and plr.Team == player.Team then return false end
    if Aimbot.Whitelist[plr.Name] then return false end
    return true
end

local function hasLineOfSight(targetHead)
    if not Aimbot.WallCheck then return true end
    local raycastParams = RaycastParams.new()
    raycastParams.FilterType = Enum.RaycastFilterType.Exclude
    raycastParams.FilterDescendantsInstances = {player.Character}
    local result = Workspace:Raycast(camera.CFrame.Position, (targetHead.Position - camera.CFrame.Position).Unit * 500, raycastParams)
    return not result or result.Instance:IsDescendantOf(targetHead.Parent)
end

local function getClosestPlayer()
    if Aimbot.LockPlayer and Aimbot.LockPlayer ~= "" then
        local target = Players:FindFirstChild(Aimbot.LockPlayer)
        if target and isValidTarget(target) then
            local head = target.Character:FindFirstChild("Head")
            if head and hasLineOfSight(head) then
                return target
            end
        end
        return nil
    end

    local closest = nil
    local shortestDist = math.huge
    local center = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)

    for _, plr in ipairs(Players:GetPlayers()) do
        if isValidTarget(plr) then
            local head = plr.Character:FindFirstChild("Head")
            if head then
                local screenPos, onScreen = camera:WorldToViewportPoint(head.Position)
                if onScreen then
                    local dist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude
                    if dist < shortestDist then
                        if hasLineOfSight(head) then
                            if Aimbot.ShowFOV then
                                if dist <= Aimbot.FOVSize then
                                    shortestDist = dist
                                    closest = plr
                                end
                            else
                                shortestDist = dist
                                closest = plr
                            end
                        end
                    end
                end
            end
        end
    end
    return closest
end

local lastFire = 0

RunService.RenderStepped:Connect(function()
    if FOVFrame then
        FOVFrame.Visible = Aimbot.ShowFOV
        FOVFrame.Size = UDim2.fromOffset(Aimbot.FOVSize * 2, Aimbot.FOVSize * 2)
    end

    if not Aimbot.Enabled then
        Aimbot.Target = nil
    else
        local target = getClosestPlayer()
        Aimbot.Target = target

        if target and target.Character and target.Character:FindFirstChild("Head") then
            local head = target.Character.Head
            local targetPos = head.Position

            if Aimbot.Smoothness >= 100 then
                camera.CFrame = CFrame.new(camera.CFrame.Position, targetPos)
            else
                local smooth = Aimbot.Smoothness / 100
                camera.CFrame = camera.CFrame:Lerp(CFrame.new(camera.CFrame.Position, targetPos), smooth)
            end

            if Aimbot.AutoFire then
                if tick() - lastFire >= Aimbot.FireDelay then
                    lastFire = tick()
                    local char = player.Character
                    local tool = char and char:FindFirstChildOfClass("Tool")
                    if tool then
                        pcall(function() tool:Activate() end)
                    end
                end
            end
        end
    end
end)

local function getKillAuraTargets()
    local targets = {}
    local char = player.Character
    if not char then return targets end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return targets end

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player and plr.Character then
            local targetRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            local humanoid = plr.Character:FindFirstChild("Humanoid")
            if targetRoot and humanoid and humanoid.Health > 0 then
                if (targetRoot.Position - root.Position).Magnitude <= KillAura.Range then
                    if not Aimbot.Whitelist[plr.Name] then
                        if not Aimbot.TeamCheck or plr.Team ~= player.Team then
                            table.insert(targets, plr)
                        end
                    end
                end
            end
        end
    end
    return targets
end

local lastHitNotify = 0
local function notifyHit(targetName, damage)
    if tick() - lastHitNotify < 0.5 then return end
    lastHitNotify = tick()
    Library:Notify({ Title = "杀戮光环", Description = "已命中: " .. targetName .. " | 伤害: " .. damage, Time = 3 })
end

local function sendV1Event(target)
    local tool = getEquippedWeapon()
    if not tool then return end
    local char = player.Character
    local head = char and char:FindFirstChild("Head")
    local targetHead = target.Character and target.Character:FindFirstChild("Head")
    if not head or not targetHead then return end

    pcall(function()
        local rf = ReplicatedStorage.KnitFolder.Knit.Services.FirearmService.RF.Fire
        local args = {
            [1] = tool.Name,
            [2] = head.Position,
            [3] = (targetHead.Position - head.Position).Unit,
            [4] = tick(),
            [5] = KillAura.FixedDamage,
            [6] = "Head"
        }
        rf:InvokeServer(unpack(args))
    end)
end

local function sendV2Event(target)
    local tool = getEquippedWeapon()
    if not tool then return end
    local handle = tool:FindFirstChild("Handle")
    local char = player.Character
    local head = char and char:FindFirstChild("Head")
    local targetHead = target.Character and target.Character:FindFirstChild("Head")
    local targetHumanoid = target.Character and target.Character:FindFirstChild("Humanoid")
    if not head or not targetHead or not targetHumanoid then return end

    pcall(function()
        local services = ReplicatedStorage.KnitFolder.Knit.Services
        local firePos = handle and handle.Position or head.Position
        local hitPos = targetHead.Position
        local damage = KillAura.FixedDamage
        local weaponName = tool.Name

        if services.FirearmService and services.FirearmService.RF then
            local rfDamage = services.FirearmService.RF:FindFirstChild("Damage")
            if rfDamage then
                rfDamage:InvokeServer(target, "Head", damage, weaponName, hitPos)
                return
            end
            local rfHit = services.FirearmService.RF:FindFirstChild("Hit")
            if rfHit then
                rfHit:InvokeServer(target.Character, targetHead, hitPos, damage, weaponName)
                return
            end
        end

        if services.FirearmService and services.FirearmService.RE then
            local reHit = services.FirearmService.RE:FindFirstChild("Hit")
            if reHit then
                reHit:FireServer(target.Character, targetHead, hitPos, damage, weaponName)
                return
            end
            local reDamage = services.FirearmService.RE:FindFirstChild("Damage")
            if reDamage then
                reDamage:FireServer(target, "Head", damage, weaponName, hitPos)
                return
            end
        end

        if services.WeaponService and services.WeaponService.RF then
            local wsDamage = services.WeaponService.RF:FindFirstChild("Damage")
            if wsDamage then
                wsDamage:InvokeServer(target, damage, weaponName, "Head")
                return
            end
        end

        if services.WeaponService and services.WeaponService.RE then
            local wsHit = services.WeaponService.RE:FindFirstChild("Hit")
            if wsHit then
                wsHit:FireServer(target.Character, hitPos, damage, weaponName)
                return
            end
        end

        if services.DamageService and services.DamageService.RF then
            local ds = services.DamageService.RF:FindFirstChild("DealDamage")
            if ds then
                ds:InvokeServer(targetHumanoid, damage, player, weaponName)
                return
            end
        end
    end)
end

local function sendV3Event(target)
    local tool = getEquippedWeapon()
    if not tool then return end
    local char = player.Character
    local head = char and char:FindFirstChild("Head")
    local targetHead = target.Character and target.Character:FindFirstChild("Head")
    local targetHumanoid = target.Character and target.Character:FindFirstChild("Humanoid")
    if not head or not targetHead or not targetHumanoid then return end

    pcall(function()
        local services = ReplicatedStorage.KnitFolder.Knit.Services
        local args1 = {
            tool.Name,
            head.Position,
            (targetHead.Position - head.Position).Unit,
            tick(),
            KillAura.FixedDamage,
            "Head"
        }
        local args2 = {
            target.Character,
            targetHead,
            targetHead.Position,
            KillAura.FixedDamage,
            tool.Name
        }
        local args3 = {
            target,
            "Head",
            KillAura.FixedDamage,
            tool.Name,
            targetHead.Position
        }
        local args4 = {
            targetHumanoid,
            KillAura.FixedDamage,
            player,
            tool.Name
        }

        for _, service in pairs(services:GetChildren()) do
            local rfFolder = service:FindFirstChild("RF")
            if rfFolder then
                for _, remote in pairs(rfFolder:GetChildren()) do
                    if remote:IsA("RemoteFunction") then
                        pcall(function() remote:InvokeServer(unpack(args1)) end)
                        pcall(function() remote:InvokeServer(unpack(args2)) end)
                        pcall(function() remote:InvokeServer(unpack(args3)) end)
                        pcall(function() remote:InvokeServer(unpack(args4)) end)
                    end
                end
            end
            local reFolder = service:FindFirstChild("RE")
            if reFolder then
                for _, remote in pairs(reFolder:GetChildren()) do
                    if remote:IsA("RemoteEvent") then
                        pcall(function() remote:FireServer(unpack(args1)) end)
                        pcall(function() remote:FireServer(unpack(args2)) end)
                        pcall(function() remote:FireServer(unpack(args3)) end)
                        pcall(function() remote:FireServer(unpack(args4)) end)
                    end
                end
            end
        end
    end)
end

local function sendKillAuraEvent(target)
    if KillAura.Version == "v1" then
        sendV1Event(target)
    elseif KillAura.Version == "v2" then
        sendV2Event(target)
    else
        sendV3Event(target)
    end
end

RunService.Heartbeat:Connect(function()
    if not KillAura.Enabled then return end
    if tick() - KillAura.LastAttack < KillAura.Interval then return end
    KillAura.LastAttack = tick()

    local tool = getEquippedWeapon()
    if not tool then return end

    local targets = getKillAuraTargets()
    for _, target in ipairs(targets) do
        sendKillAuraEvent(target)
        pcall(function() tool:Activate() end)
        notifyHit(target.Name, KillAura.FixedDamage)
    end
end)

local function createESPObjects(plr)
    if ESP.Objects[plr] then return end
    local box = Drawing.new("Square")
    box.Visible = false
    box.Thickness = 1.5
    box.Filled = false
    box.Color = ESP.Color

    local nameText = Drawing.new("Text")
    nameText.Visible = false
    nameText.Size = 14
    nameText.Center = true
    nameText.Outline = true
    nameText.Color = Color3.new(1, 1, 1)

    local infoText = Drawing.new("Text")
    infoText.Visible = false
    infoText.Size = 12
    infoText.Center = true
    infoText.Outline = true
    infoText.Color = Color3.new(1, 1, 1)

    ESP.Objects[plr] = {
        Box = box,
        Name = nameText,
        Info = infoText,
    }
end

local function removeESPObjects(plr)
    local obj = ESP.Objects[plr]
    if not obj then return end
    pcall(function() obj.Box:Remove() end)
    pcall(function() obj.Name:Remove() end)
    pcall(function() obj.Info:Remove() end)
    ESP.Objects[plr] = nil
end

local function updateESP()
    for plr, obj in pairs(ESP.Objects) do
        if not plr or not plr.Parent then
            removeESPObjects(plr)
        end
    end

    if not ESP.Enabled then
        for _, obj in pairs(ESP.Objects) do
            obj.Box.Visible = false
            obj.Name.Visible = false
            obj.Info.Visible = false
        end
        return
    end

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player and plr.Character then
            local humanoid = plr.Character:FindFirstChild("Humanoid")
            local head = plr.Character:FindFirstChild("Head")
            local root = plr.Character:FindFirstChild("HumanoidRootPart")
            if humanoid and head and root and humanoid.Health > 0 then
                if not Aimbot.Whitelist[plr.Name] then
                    createESPObjects(plr)
                    local obj = ESP.Objects[plr]
                    if obj then
                        local pos, onScreen = camera:WorldToViewportPoint(root.Position)
                        local headPos = camera:WorldToViewportPoint(head.Position)
                        local legPos = camera:WorldToViewportPoint(root.Position - Vector3.new(0, 3, 0))

                        if onScreen then
                            local height = math.abs(headPos.Y - legPos.Y)
                            local width = height * 0.6
                            local boxPos = Vector2.new(pos.X - width / 2, headPos.Y)

                            obj.Box.Visible = ESP.ShowBox
                            obj.Box.Size = Vector2.new(width, height)
                            obj.Box.Position = boxPos
                            obj.Box.Color = ESP.Color

                            obj.Name.Visible = ESP.ShowName
                            obj.Name.Position = Vector2.new(pos.X, headPos.Y - 18)
                            obj.Name.Text = plr.Name
                            obj.Name.Color = ESP.Color

                            local dist = math.floor((root.Position - camera.CFrame.Position).Magnitude)
                            local health = math.floor(humanoid.Health)
                            local maxHealth = math.floor(humanoid.MaxHealth)
                            local infoStr = ""
                            if ESP.ShowHealth then
                                infoStr = infoStr .. health .. "/" .. maxHealth .. "HP "
                            end
                            if ESP.ShowDistance then
                                infoStr = infoStr .. dist .. "m"
                            end
                            obj.Info.Visible = (ESP.ShowHealth or ESP.ShowDistance) and infoStr ~= ""
                            obj.Info.Position = Vector2.new(pos.X, legPos.Y + 4)
                            obj.Info.Text = infoStr
                            obj.Info.Color = Color3.new(1, 1, 1)
                        else
                            obj.Box.Visible = false
                            obj.Name.Visible = false
                            obj.Info.Visible = false
                        end
                    end
                end
            end
        end
    end
end

RunService.RenderStepped:Connect(updateESP)

Players.PlayerRemoving:Connect(function(plr)
    removeESPObjects(plr)
end)

