        Time = 5,
    })
end

task.spawn(function()
    while true do
        if killAuraEnabled and remoteEvent then
            local char = player.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if root then
                local npcsFolder = workspace:FindFirstChild("NPCs")
                if npcsFolder then
                    local targets = {}
                    for _, npc in ipairs(npcsFolder:GetChildren()) do
                        local humanoid = npc:FindFirstChildOfClass("Humanoid")
                        if humanoid then
                            local npcRoot = npc:FindFirstChild("HumanoidRootPart") or npc:FindFirstChild("Torso") or npc:FindFirstChild("Head")
                            if npcRoot and npcRoot:IsA("BasePart") then
                                local dist = (root.Position - npcRoot.Position).Magnitude
                                if dist <= killAuraRange then
                                    table.insert(targets, {
                                        humanoid = humanoid,
                                        distance = dist,
                                    })
                                end
                            end
                        end
                    end
                    table.sort(targets, function(a, b)
                        return a.distance < b.distance
                    end)
                    for _, target in ipairs(targets) do
                        local args = {
                            [1] = "NPCs",
                            [2] = "Damage",
                            [3] = target.humanoid,
                            [4] = killAuraDamage,
                        }
                        remoteEvent:FireServer(unpack(args))
                    end
                end
            end
            task.wait(killAuraFrequency)
        else
            task.wait(0.1)
        end
    end
end)

