local function WaitForChildTimeout(parent, name, timeout)
    if not parent then return nil end
    local child = parent:FindFirstChild(name)
    if child then return child end
    local t = 0
    while t < timeout do
        task.wait(0.1)
        t = t + 0.1
        child = parent:FindFirstChild(name)
        if child then return child end
    end
    return nil
end

local Network = WaitForChildTimeout(ReplicatedStorage, "Network", 5)
local MeleeHitEvent = Network and WaitForChildTimeout(Network, "MeleeHitEvent", 5) or nil
if not MeleeHitEvent then
    local MELEE_KEYWORDS = { "MELEE", "HIT", "SLASH", "SWING", "ATTACK", "KILL", "DAMAGE", "HURT" }
    for _, evt in ipairs(ReplicatedStorage:GetDescendants()) do
        if evt:IsA("RemoteEvent") then
            local upName = string.upper(evt.Name)
            for _, kw in ipairs(MELEE_KEYWORDS) do
                if string.find(upName, kw, 1, true) then
                    MeleeHitEvent = evt
                    print("[武器调试] 近战事件关键字兜底探测到:", evt.Name, "(路径:", evt:GetFullName(), ")")
                    break
                end
            end
            if MeleeHitEvent then break end
        end
    end
end
if not MeleeHitEvent then
    warn("[多武器杀戮] 未找到 MeleeHitEvent，近战击杀功能不可用（但UI仍会创建）")
end

local GunHitEvent = nil
do
    local network = ReplicatedStorage:FindFirstChild("Network")
    local possibleNames = {
        "GunHitEvent", "ShootEvent", "FireEvent", "HitEvent",
        "DamageEvent", "WeaponHitEvent", "BulletHitEvent", "RaycastHitEvent"
    }
    if network then
        for _, name in ipairs(possibleNames) do
            local evt = network:FindFirstChild(name)
            if evt and evt:IsA("RemoteEvent") then
                GunHitEvent = evt
                print("[武器调试] 自动探测到枪械事件:", name)
                break
            end
        end
    end
    if not GunHitEvent then
        local GUN_KEYWORDS = { "GUN", "SHOOT", "FIRE", "HIT", "DAMAGE", "WEAPON", "BULLET", "RAYCAST", "ATTACK", "MELEE" }
        for _, evt in ipairs(ReplicatedStorage:GetDescendants()) do
            if evt:IsA("RemoteEvent") then
                local upName = string.upper(evt.Name)
                for _, kw in ipairs(GUN_KEYWORDS) do
                    if string.find(upName, kw, 1, true) then
                        GunHitEvent = evt
                        print("[武器调试] 关键字兜底探测到枪械/命中事件:", evt.Name, "(路径:", evt:GetFullName(), ")")
                        break
                    end
                end
                if GunHitEvent then break end
            end
        end
    end
    if not GunHitEvent then
        warn("[武器调试] 未能自动探测枪械远程事件，请手动在代码里设置 GunHitEvent")
    end
end

local GAMEFOLDERS = Workspace:FindFirstChild("GAMEFOLDERS")
local CustomersFolder = GAMEFOLDERS and GAMEFOLDERS:FindFirstChild("Customers") and GAMEFOLDERS.Customers:FindFirstChild("Alive")
local CustomersDeadFolder = GAMEFOLDERS and GAMEFOLDERS:FindFirstChild("Customers") and (GAMEFOLDERS.Customers:FindFirstChild("Dead") or GAMEFOLDERS.Customers:FindFirstChild("DeadCustomers"))
local NPCsFolder = GAMEFOLDERS and GAMEFOLDERS:FindFirstChild("NPCs")

local NPCTags = {
    Customer = {},
    Enemy = {},
}

local COPS = CONFIG.EnemyCategories.Cop
local RATS = CONFIG.EnemyCategories.Rat
local COP_KEYWORDS = { "COP", "POLICE", "OFFICER", "SWAT", "RIOT", "SNIPER", "UNDERCOVER" }
local RAT_KEYWORDS = { "RAT" }

local function NameMatchesKeywords(name, keywords)
    if not name then return false end
    local upName = string.upper(name)
    for _, kw in ipairs(keywords) do
        if string.find(upName, kw, 1, true) then
            return true
        end
    end
    return false
end

local function IsEnemyCategory(model)
    if not model or not model:IsA("Model") then return false end
    if not model:FindFirstChild("Humanoid") then return false end
    local name = model.Name
    if COPS[name] == true or RATS[name] == true then return true end
    if NameMatchesKeywords(name, COP_KEYWORDS) then return true end
    if NameMatchesKeywords(name, RAT_KEYWORDS) then return true end
    return false
end

local function IsCop(model)
    if not model or not model:IsA("Model") then return false end
    local name = model.Name
    if COPS[name] == true then return true end
    return NameMatchesKeywords(name, COP_KEYWORDS)
end

local function IsRat(model)
    if not model or not model:IsA("Model") then return false end
    local name = model.Name
    if RATS[name] == true then return true end
    return NameMatchesKeywords(name, RAT_KEYWORDS)
end

local function ClassifyNPC(model)
    if not model or not model:IsA("Model") then return nil end
    if not model:FindFirstChild("Humanoid") then return nil end
    if CustomersFolder and model.Parent == CustomersFolder then
        return "customer"
    end
    if IsCop(model) then return "cop" end
    if IsRat(model) then return "rat" end
    if NPCsFolder and model:IsDescendantOf(NPCsFolder) then
        return "enemy"
    end
    return nil
end

local ESP_Enabled = false

local function AddEnemy(model)
    if not model or not model.Parent then return end
    for _, e in ipairs(NPCTags.Enemy) do
        if e == model then return end
    end
    table.insert(NPCTags.Enemy, model)
end

local function ScanAll()
    table.clear(NPCTags.Customer)
    table.clear(NPCTags.Enemy)
    if CustomersFolder then
        for _, model in ipairs(CustomersFolder:GetChildren()) do
            if model:IsA("Model") and model:FindFirstChild("Humanoid") then
                table.insert(NPCTags.Customer, model)
            end
        end
    end
    if NPCsFolder then
        for _, model in ipairs(NPCsFolder:GetChildren()) do
            if model:IsA("Model") and model.Name ~= "Dead" and model:FindFirstChild("Humanoid") then
                AddEnemy(model)
            end
        end
    end
    for _, model in ipairs(Workspace:GetDescendants()) do
        if IsEnemyCategory(model) then
            AddEnemy(model)
        end
    end
end

ScanAll()

if CustomersFolder then
    CustomersFolder.ChildAdded:Connect(function(child)
        task.wait(0.1)
        if child:IsA("Model") and child:FindFirstChild("Humanoid") then
            table.insert(NPCTags.Customer, child)
        end
    end)
else
    warn("[多武器杀戮] 未找到顾客Alive文件夹，动态顾客监听已跳过")
end

if NPCsFolder then
    NPCsFolder.ChildAdded:Connect(function(child)
        task.wait(0.1)
        if child:IsA("Model") and child.Name ~= "Dead" and child:FindFirstChild("Humanoid") then
            AddEnemy(child)
            print("[敌人刷新]", child.Name)
        end
    end)
    NPCsFolder.ChildRemoved:Connect(function(child)
        for i, v in ipairs(NPCTags.Enemy) do
            if v == child then
                table.remove(NPCTags.Enemy, i)
                break
            end
        end
    end)
end

Workspace.DescendantAdded:Connect(function(desc)
    task.wait(0.1)
    if desc:IsA("Model") and desc:FindFirstChild("Humanoid") then
        if IsEnemyCategory(desc) then
            AddEnemy(desc)
        end
